func moveFile(src, dst string) error {
	err := rename(src, dst)
	if err == nil {
		return nil
	}
	srcInfo, statErr := os.Lstat(src)
	if statErr != nil {
		return err
	}
	dstInfo, statErr := os.Lstat(dst)
